zmq::context_t ctx(1);
zmq::socket_t sub(ctx, zmq::socket_type::sub);
sub.set(zmq::sockopt::subscribe, "control/orders-adapter/cmd");
sub.connect("tcp://control-bus:5559");
std::unordered_map<std::string, std::function<std::string(const json&)>> handlers{
    {"status", [](const json&) { return snapshot_json(); }},
    {"pause",  [](const json&) { router.pause(); return std::string("{\"applied\":true}"); }},
};
for (;;) {
    zmq::message_t topic, payload;
    sub.recv(topic); sub.recv(payload);
    const auto cmd = json::parse(payload.to_string());
    publish_status(handlers.at(cmd["op"])(cmd), cmd["id"]);
}

