// control.proto: service Control { rpc Snapshot(Empty) returns (SnapshotReply); rpc Suspend(Reason) returns (Ack); }
class ControlImpl final : public Control::Service {
  grpc::Status Snapshot(grpc::ServerContext*, const Empty*, SnapshotReply* out) override {
    fill_snapshot(*out); return grpc::Status::OK;
  }
  grpc::Status Suspend(grpc::ServerContext*, const Reason* why, Ack* ack) override {
    router_.suspend(why->text()); ack->set_applied(true); return grpc::Status::OK;
  }
};
